<?php declare(strict_types=1);
use Kulturhus\Verein\{Finance,Settings,SettingsSchema,Permissions,ContributionInvoices,ContributionReminders};
use Kulturhus\Verein\Finance\Contributions\{ContributionRunInput,ContributionRunDraft,ContributionRunRequests};
use Kulturhus\Native\Shared\Db;

/** Actual annual dues, ordinary generated originals and durable orders; no transport. */
function ownContributionRunContracts(PDO $db,callable $check):array
{
    if(!preg_match('/\Akh_(?:test|native)_[a-f0-9]{24}\z/D',(string)$db->query('SELECT DATABASE()')->fetchColumn()))throw new RuntimeException('Owned contribution contracts required.');
    $club='own-contribution-native';$admin='own-contribution-admin';$actor='own-contribution-finance';
    $db->exec("INSERT INTO clubs VALUES('own-contribution-native','Own native contribution association'),('own-contribution-foreign','Own foreign contribution association');INSERT INTO actors(id,club_id,role,is_superuser)VALUES('own-contribution-admin','own-contribution-native','members',1),('own-contribution-finance','own-contribution-native','treasurer',0),('own-contribution-other','own-contribution-native','treasurer',0),('own-contribution-general','own-contribution-native','members',0),('own-contribution-foreign','own-contribution-foreign','treasurer',0)");
    $settings=new Settings($db,$admin);$finance=new Finance($db,$actor);$account=$finance->createAccount('Own contribution bank','offline','0','2026-01-01');
    $generalRole=$settings->saveRole('',0,['name'=>'Own contribution General only','members_access'=>'none','finance_access'=>'none','settings_access'=>true]);$settings->assignRole('own-contribution-general',$generalRole,0);
    $financeRoleData=['name'=>'Own contribution Finance only','members_access'=>'none','finance_access'=>'write','settings_access'=>false];$financeRole=$settings->saveRole('',0,$financeRoleData);$settings->assignRole($actor,$financeRole,0);
    $check(!(new Settings($db,$actor))->canManage()&&Permissions::actor($db,$actor)['members_access']==='none'&&Permissions::actor($db,$actor)['finance_access']==='write','actual contribution author has Finance writing without General or member administration');
    $check((new Settings($db,'own-contribution-general'))->canManage()&&Permissions::actor($db,'own-contribution-general')['finance_access']==='none','actual contribution General-only account has no financial permission');
    foreach(['club'=>['name'=>'Own original contribution association','street'=>'Own original seller street','postcode'=>'12345','city'=>'Own seller town'],'bank'=>['iban'=>'DE89370400440532013000','holder'=>'Own contribution association','account_id'=>$account]]as$section=>$values)$settings->save($section,array_replace(SettingsSchema::defaults($section),$values),0);
    $payer=static function(string$id)use($db,$club):void{Db::run($db,"INSERT INTO contacts(id,club_id,kind,name,email,address)VALUES(?,?,'person',?,?,?)",[$id,$club,'Own contribution payer '.$id,$id.'@example.invalid','Testweg 2, 00000 Musterort']);Db::run($db,"INSERT INTO memberships(id,club_id,contact_id,member_number,status,starts_on)VALUES(?,?,?,?, 'aktiv','2025-01-01')",['membership-'.$id,$club,$id,'OWN-'.$id]);};
    $payer('own-existing-payer');$existing=$finance->createAnnualContribution('own-existing-payer',2026,'','2026-01-01');$invoice=(new ContributionInvoices($db,$actor))->issue($existing);$payer('own-new-payer');
    $check($invoice['state']==='issued'&&Permissions::actor($db,$actor)['settings_access']==0,'Finance-only author creates an actual complete issued contribution PDF without General authority');
    require_once __DIR__.'/original-database-hash.php';$tables=$db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);$requests=new ContributionRunRequests($db,$actor);$input=['data'=>['day'=>'2026-01-01']];$key=static fn():string=>bin2hex(random_bytes(16));
    $deny=static function(callable$operation,int$code,string$label)use($check):void{try{$operation();}catch(DomainException$failure){$check($failure->getCode()===$code,$label);return;}throw new RuntimeException('Expected rejection: '.$label);};
    foreach(["0\n","2026-01-01\0",str_repeat('🙂',1001),'2025-01-01','2027-01-01']as$day){$whole=['data'=>['day'=>$day]];$check(ContributionRunInput::capture($whole)===$whole,'whole contribution date preserves invalid raw Unicode blank zero and year before explicit review');$deny(fn()=>$requests->prepare($whole),422,'invalid whole contribution day has a precise review rejection without a parser failure');}
    $session=[];$originalDraft=ContributionRunDraft::open($session,Permissions::actor($db,$actor),['data'=>['day'=>"\n0\n"]]);$check($originalDraft['input']['data']['day']==="\n0\n"&&ContributionRunDraft::get($session,Permissions::actor($db,$actor),$originalDraft['id'])===$originalDraft,'account-bound private contribution draft preserves the entire original leading blank zero');ContributionRunDraft::discard($session,$originalDraft);
    $before=ownOriginalDatabaseHash($db,$tables);$review=$requests->prepare($input);$check(count($review['plan']['annual_candidates'])===2&&$review['plan']['annual_due']===true&&$review['normalized']['day']==='2026-01-01','native annual review binds actual existing and genuinely new payable memberships');$check($requests->prepare($input)['hash']===$review['hash']&&ownOriginalDatabaseHash($db,$tables)===$before,'repeat native contribution review is stable and preserves every entire earlier business row');
    $deny(fn()=>$requests->accept($input,$key(),$review['hash'],false),422,'unapproved contribution review creates no financial entry PDF delivery or private first');
    $db->exec("CREATE TRIGGER own_contribution_first_abort BEFORE INSERT ON native_settings_requests FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Own contribution final-original abort'");$db->beginTransaction();
    try{
        Db::run($db,'UPDATE clubs SET name=? WHERE id=?',['Own earlier contribution caller work',$club]);$earlier=ownOriginalDatabaseHash($db,$tables);$aborted=false;
        try{$requests->accept($input,$key(),$review['hash'],true);}catch(PDOException$failure){if(($failure->errorInfo[0]??null)!=='45000')throw$failure;$aborted=true;}
        $check($aborted&&$db->inTransaction()&&ownOriginalDatabaseHash($db,$tables)===$earlier,'actual SQL abort after new annual ledger PDF and delivery work rolls back the whole inner batch while preserving earlier caller work');
    }finally{if($db->inTransaction())$db->rollBack();$db->exec('DROP TRIGGER own_contribution_first_abort');}
    $check(ownOriginalDatabaseHash($db,$tables)===$before,'failed native annual batch retains every complete original row and key');
    $first=$requests->accept($input,$key(),$review['hash'],true);$check($first['result']['created']===1&&$first['result']['queued']===2&&count($first['result']['contributions'])===2&&count($first['result']['deliveries'])===2&&$first['result']['errors']===[],'conscious Finance-only annual batch atomically records one real new contribution and two genuine private delivery orders');
    $after=ownOriginalDatabaseHash($db,$tables);$check($requests->accept($input,$first['key'],$review['hash'],true)===$first&&$requests->receipt($first['key'])===$first&&ownOriginalDatabaseHash($db,$tables)===$after,'same annual scheduling key reads its exact first original without repeating any business row');
    $check($first['review']['input']===$input&&str_contains($first['original_json'],'dvm-contribution-run-original/1')&&preg_match('/\.\d{6}Z\z/D',$first['created_at'])===1,'actual first annual confirmation retains whole intention source result and real microsecond time');
    foreach(['own-contribution-other'=>404,'own-contribution-general'=>403,'own-contribution-foreign'=>404]as$other=>$code)$deny(fn()=>(new ContributionRunRequests($db,$other))->receipt($first['key']),$code,'known actual personal contribution first remains private from '.$other);
    $settings->saveRole($financeRole,1,array_replace($financeRoleData,['finance_access'=>'read']));$readOnlyBefore=ownOriginalDatabaseHash($db,$tables);$check($requests->receipt($first['key'])===$first&&$requests->accept($input,$first['key'],$review['hash'],true)===$first&&ownOriginalDatabaseHash($db,$tables)===$readOnlyBefore,'withdrawn write role can read and repeat its exact accepted contribution outcome without a new write');$deny(fn()=>$requests->prepare($input),403,'current Finance reading cannot approve a new contribution run');$settings->saveRole($financeRole,2,$financeRoleData);
    $check((int)Db::run($db,'SELECT COUNT(*) FROM finance_transactions WHERE club_id=?',[$club])->fetchColumn()===0,'native annual scheduling creates no payment or refund');
    return compact('club','admin','actor','settings','finance','account','payer','existing','invoice','requests','input','review','first','tables','key','deny','financeRole','financeRoleData');
}
